 $('shotStyle').addEventListener('change',()=>control.poseController.shot=$('shotStyle').value);
 for(const id of ['bowlingArm','wicketSide','actionStyle'])$(id).addEventListener('change',()=>{action.arm=$('bowlingArm').value||'right';action.wicket=$('wicketSide').value||'over';action.style=$('actionStyle').value||'semi';});
 $('quality').addEventListener('change',()=>quality.apply($('quality').value));
 function configure(){control.mode=$('inputMode').value;control.sensitivity=Number($('sensitivity').value);control.invert=$('invert').checked;control.hand=$('hand').value;$('sensitivityValue').textContent=control.sensitivity.toFixed(1)+'×';$('inputLabel').textContent=control.mode==='trackpad'?'TWO-FINGER TRACKPAD':control.mode==='touch'?'TOUCH SWIPE':'MOUSE MOTION';$('hint').textContent=control.mode==='trackpad'?'TWO FINGERS: PULL BACK, THEN SWIPE FORWARD':'MOVE TO POSITION · STROKE FORWARD TO SWING';}
