  $('paceSlider').value='120';$('paceValue').value='120';$('paceMin').value='110';$('paceMax').value='125';
  for(const id of ['paceMode','paceMin','paceMax','paceVary'])$(id).addEventListener('input',configureSpeed);
  $('paceValue').addEventListener('input',()=>{$('paceSlider').value=$('paceValue').value;configureSpeed();});$('paceSlider').addEventListener('input',()=>{$('paceValue').value=$('paceSlider').value;configureSpeed();});
  $('paceBand').addEventListener('change',()=>{const bands=[[80,100],[110,125],[130,145],[145,155],[155,165]],band=bands[Number($('paceBand').value)];if(!band)return;$('paceMin').value=String(band[0]);$('paceMax').value=String(band[1]);$('paceValue').value=String((band[0]+band[1])/2);$('paceSlider').value=$('paceValue').value;configureSpeed();});configureSpeed();
  $('lookToggle').onclick=()=>{view.looking=!view.looking;view.last=null;$('lookToggle').textContent=view.looking?'BATTING · L':'LOOK · L';};$('centerView').onclick=()=>view.center();
  view.attach(canvas,{blocked:()=>!!activeModal,onMode:looking=>{$('lookToggle').textContent=looking?'BATTING · L':'LOOK · L';}});
  control.onActivity=text=>{$('activity').textContent=text;};
  function audioHit(freq,duration,volume=.07){if(!soundOn)return;audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.3),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
  function score(){ $('score').innerHTML=`${ledger.contacts}<span>/${ledger.deliveries}</span>`;$('over').textContent=`${Math.floor(ledger.legalBalls/6)}.${ledger.legalBalls%6}`;$('chase').textContent=`${ledger.wickets} bowled · ${ledger.boundaryRuns} boundary runs · ${ledger.deliveries} deliveries`;$('contactRate').textContent=ledger.deliveries?Math.round(ledger.contacts/ledger.deliveries*100)+'%':'—';const recent=ledger.events.slice(-6);$('deliveries').innerHTML='<span>CONTACTS / BALLS</span>'+Array.from({length:6},(_,i)=>`<i class="${recent[i]?'filled':''}">${recent[i]?recent[i].contacts-(ledger.events[ledger.events.indexOf(recent[i])-1]?.contacts||0)?'●':'·':'—'}</i>`).join('');}
