  function showAnalysis(){$('pacePanel').open=false;ledger.commit(deliveryId,sim.events);score();state='result';control.active=false;const pitched=sim.events.find(e=>e.type==='BallPitched'),contact=sim.contact;const result=sim.result==='MISSED'?(sim.events.some(e=>e.type==='WideDetected')?'WIDE':'MISSED'):sim.result;
    $('resultTitle').textContent=result==='IN PLAY'?'BAT CONTACT':result;$('resultDetail').textContent=contact?('Contact: '+contact.region+'.')+' Review the path below.':result==='BOWLED'?'The ball crossed the wicket.':'No bat contact. Reset and read the next action.';
    $('releaseSpeed').textContent=(length(sim.release.velocity)*3.6).toFixed(1)+' km/h';$('bounceDistance').textContent=pitched?(RULES.stumpZ-pitched.position.z).toFixed(2)+' m':'Full toss';$('batSpeed').textContent=contact?(contact.batSpeedMps*3.6).toFixed(1)+' km/h':'—';$('contactPoint').textContent=contact?`${Math.round(contact.batLocalM.x*1000)} / ${Math.round(contact.batLocalM.y*1000)} mm`:'No contact';reactions.trigger(result==='SIX'?'six':result==='FOUR'?'four':result==='BOWLED'?'wicket':'miss');stadiumAudio.event(result==='SIX'?'six':result==='FOUR'?'four':result==='BOWLED'?'wicket':'miss');$('analysis').classList.remove('hidden');$('activity').textContent='DELIVERY COMPLETE';$('scrub').max=sim.time.toFixed(3);$('scrub').value='0';$('feedback').innerHTML='';
  }
  function renderBat(p){const axes=batBasis(p.yaw,p.loft,p.roll),matrix=new THREE.Matrix4().makeBasis(new THREE.Vector3(axes.right.x,axes.right.y,axes.right.z),new THREE.Vector3(axes.up.x,axes.up.y,axes.up.z),new THREE.Vector3(-axes.normal.x,-axes.normal.y,-axes.normal.z));batRig.quaternion.setFromRotationMatrix(matrix);batRig.position.set(p.position.x,p.position.y,p.position.z);}
  function togglePause(){if(state==='ready'||activeModal)return;paused=!paused;control.keys.clear();control.lastPointer=null;$('pause').textContent=paused?'▶':'Ⅱ';$('activity').textContent=paused?'PAUSED':'READY';}
