    if(state==='replay'&&sim){if(!paused)replayTime=Math.min(sim.time,replayTime+elapsed*replaySpeed);const a=sim.frames[Math.min(sim.frames.length-1,Math.floor(replayTime/.01))];ball.position.set(a.position.x,a.position.y,a.position.z);if(a.bat)pose=a.bat;$('scrub').value=String(replayTime);$('replayTime').textContent=replayTime.toFixed(2)+' s';if(replayTime===sim.time)paused=true;}
    if(sim){const seam=state==='replay'?sim.frames[Math.min(sim.frames.length-1,Math.floor(replayTime/.01))].seamNormal:sim.seamNormal;const n=new THREE.Vector3(seam.x,seam.y,seam.z);ball.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),n);}
